import java.util.Scanner;

public class Main {
    static class DSU {
        int[] parent;
        int[] size;

        void initialize(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; ++i) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int findParent(int x) {
            if (parent[x] != x) {
                parent[x] = findParent(parent[x]);
            }
            return parent[x];
        }

        void unionSets(int a, int b) {
            a = findParent(a);
            b = findParent(b);
            if (a != b) {
                if (size[a] < size[b]) {
                    int temp = a;
                    a = b;
                    b = temp;
                }
                parent[b] = a;
                size[a] += size[b];
            }
        }
    }

    static long modExp(long base, int exp, int mod) {
        long res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        final long MOD = 1000000007L;

        if (k == 0) {
            System.out.println(modExp(n, n - 1, (int)MOD));
            sc.close();
            return;
        }

        DSU dsu = new DSU();
        dsu.initialize(n);
        for (int i = 0; i < n; ++i) {
            int target = (int)((long)i * k % n);
            dsu.unionSets(i, target);
        }

        long total = 1;
        for (int i = 0; i < n; ++i) {
            if (dsu.findParent(i) != i) continue;
            long t = modExp(k, dsu.size[dsu.findParent(i)], n);
            if (t == 1) {
                total = (total * n) % MOD;
            }
        }
        System.out.println(total);
        sc.close();
    }
